return items.map(item => {
  return {
    json: {
      geminiRequest: {
        contents: [
          {
            parts: [
              {
                inline_data: {
                  mime_type: 'application/pdf',
                  data: item.json.pdfBase64
                }
              },
              {
                text: `Extract invoice header information from this PDF and return JSON only.

Important context:
- The expected buyer company is: Unternehmen X
- The buyer may use one of these approved addresses:
  - Musterweg 10, 04109 Leipzig, Germany
  - Musterweg 12, 04109 Leipzig, Germany
- The buyer VAT ID is: DE450224353

Critical extraction rules:
1. Distinguish clearly between seller and buyer.
2. Do not confuse the buyer VAT ID with the seller VAT ID.
3. If a VAT ID belongs to Unternehmen X, return it as "VAT-ID (Buyer)".
4. Extract the supplier VAT ID separately as "VAT-ID (Seller)".
5. If only one VAT ID is visible, decide whether it belongs to the seller or buyer based on the company name and address nearby.
6. If the seller VAT ID cannot be identified with confidence, return "not found" for "VAT-ID (Seller)".
7. Output JSON only. Do not add explanations or markdown fences.

Return exactly one JSON object with these fields:
{
  "Invoice No": "string",
  "Invoice Date": "string",
  "VAT-ID (Seller)": "string",
  "VAT-ID (Buyer)": "string",
  "Name (Seller)": "string",
  "Address (Seller)": "string",
  "Zip (Seller)": "string",
  "City (Seller)": "string",
  "Country (Seller)": "string",
  "Name (Buyer)": "string",
  "Address (Buyer)": "string",
  "Zip (Buyer)": "string",
  "City (Buyer)": "string",
  "Country (Buyer)": "string"
}

If a field is missing, return "not found".`
              }
            ]
          }
        ]
      }
    }
  };
});

function normText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normZip(value) {
  return String(value || '').replace(/\D/g, '').padStart(5, '0');
}

function normCountry(value) {
  const raw = String(value || '').trim().toLowerCase();

  const map = {
    de: 'germany',
    deutschland: 'germany',
    germany: 'germany',
    fr: 'france',
    frankreich: 'france',
    france: 'france',
    se: 'sweden',
    schweden: 'sweden',
    sweden: 'sweden',
  };

  return map[raw] || normText(value);
}

function equalsLoose(a, b) {
  return normText(a) !== '' && normText(a) === normText(b);
}

function scoreRecipient(invoice, recipient) {
  const checks = {
    buyer_name_match: equalsLoose(invoice['Name (Buyer)'], recipient.name),
    buyer_address_match: equalsLoose(invoice['Address (Buyer)'], recipient.address),
    buyer_zip_match:
      normZip(invoice['Zip (Buyer)']) !== '' &&
      normZip(invoice['Zip (Buyer)']) === normZip(recipient.zip),
    buyer_city_match: equalsLoose(invoice['City (Buyer)'], recipient.city),
    buyer_country_match:
      normCountry(invoice['Country (Buyer)']) !== '' &&
      normCountry(invoice['Country (Buyer)']) === normCountry(recipient.country),
  };

  const score =
    (checks.buyer_name_match ? 4 : 0) +
    (checks.buyer_address_match ? 2 : 0) +
    (checks.buyer_zip_match ? 2 : 0) +
    (checks.buyer_city_match ? 1 : 0) +
    (checks.buyer_country_match ? 1 : 0);

  return { checks, score };
}

return items.map(item => {
  const invoice = item.json.invoice_extracted || {};
  const master = item.json.recipient_master || {};
  const recipients = Array.isArray(master.approved_recipients) ? master.approved_recipients : [];

  let best = null;
  let bestScore = -1;
  let bestChecks = {
    buyer_name_match: false,
    buyer_address_match: false,
    buyer_zip_match: false,
    buyer_city_match: false,
    buyer_country_match: false,
  };

  for (const recipient of recipients) {
    const result = scoreRecipient(invoice, recipient);
    if (result.score > bestScore) {
      best = recipient;
      bestScore = result.score;
      bestChecks = result.checks;
    }
  }

  const passed =
    bestChecks.buyer_name_match &&
    (bestChecks.buyer_zip_match || bestChecks.buyer_city_match || bestChecks.buyer_address_match);

  const reasonCodes = [];
  if (!passed) {
    if (!bestChecks.buyer_name_match) reasonCodes.push('BUYER_NAME_MISMATCH');
    if (!bestChecks.buyer_address_match) reasonCodes.push('BUYER_ADDRESS_MISMATCH');
    if (!bestChecks.buyer_zip_match) reasonCodes.push('BUYER_ZIP_MISMATCH');
    if (!bestChecks.buyer_city_match) reasonCodes.push('BUYER_CITY_MISMATCH');
    if (!bestChecks.buyer_country_match) reasonCodes.push('BUYER_COUNTRY_MISMATCH');
  }

  return {
    json: {
      ...item.json,
      report_id: item.json.report_id || 'REP-AP-SYS-001',
      process_id: item.json.process_id || 'proc_ap_001',
      process_instance_id: item.json.process_instance_id || '',
      process_build_id: item.json.process_build_id || 'proc_ap_001@v0.1.0',
      workflow_engine: item.json.workflow_engine || 'n8n',
      workflow_id: item.json.workflow_id || 'wf_invoice_check_x',
      workflow_run_id: item.json.workflow_run_id || '',
      reported_at: item.json.reported_at || new Date().toISOString(),
      k1_result: {
        status: passed ? 'passed' : 'failed',
        control_id: 'CTRL-AP-001',
        control_title: 'Recipient identity validation for Company X',
        matched_recipient_id: best?.recipient_id || '',
        match_type: passed ? 'master_data_match' : 'no_reliable_match',
        sub_checks: bestChecks,
        reason_codes: reasonCodes,
        checked_at: new Date().toISOString(),
      },
    }
  };
});

function clean(value) {
  return String(value || '').trim();
}

function vatPrefix(vatId) {
  const value = clean(vatId).toUpperCase();
  if (value.length < 2) return '';
  return value.slice(0, 2);
}

// Mock normalization for the prototype.
// Later this should be replaced by a shared normalization function
// or a proper country-code mapping utility used across the workflow.
function normCountry(value) {
  const raw = clean(value).toLowerCase();

  const map = {
    de: 'germany',
    deutschland: 'germany',
    germany: 'germany',
    fr: 'france',
    frankreich: 'france',
    france: 'france',
    se: 'sweden',
    schweden: 'sweden',
    sweden: 'sweden',
    at: 'austria',
    oesterreich: 'austria',
    österreich: 'austria',
    austria: 'austria',
    nl: 'netherlands',
    niederlande: 'netherlands',
    netherlands: 'netherlands',
    it: 'italy',
    italien: 'italy',
    italy: 'italy',
    es: 'spain',
    spanien: 'spain',
    spain: 'spain',
    pl: 'poland',
    polen: 'poland',
    poland: 'poland',
    cz: 'czech republic',
    tschechien: 'czech republic',
    'czech republic': 'czech republic'
  };

  return map[raw] || raw;
}

return items.map(item => {
  const invoice = item.json.invoice_extracted || {};
  const sellerVat = clean(invoice['VAT-ID (Seller)']);
  const sellerCountryRaw = clean(invoice['Country (Seller)']);
  const sellerCountry = normCountry(sellerCountryRaw);
  const prefix = vatPrefix(sellerVat);

  let route = 'missing_vat';
  let rationale = 'Seller VAT ID missing or unusable.';

  if (!sellerVat || sellerVat.toLowerCase() === 'not found') {
    route = 'missing_vat';
    rationale = 'Seller VAT ID missing or unusable.';
  } else if (prefix === 'DE' || sellerCountry === 'germany') {
    route = 'domestic';
    rationale = 'Domestic invoice path, no BZSt foreign validation required.';
  } else {
    route = 'foreign';
    rationale = 'Foreign supplier VAT ID requires BZSt/API validation.';
  }

  return {
    json: {
      ...item.json,
      vat_route: {
        route,
        rationale,
        seller_vat_id: sellerVat,
        seller_country: sellerCountryRaw,
        seller_country_normalized: sellerCountry
      }
    }
  };
});

function clean(value) {
  return String(value || '').trim();
}

return items.map(item => {
  const invoice = item.json.invoice_extracted || {};
  const sellerVat = clean(invoice['VAT-ID (Seller)']);
  const buyerVat = clean(invoice['VAT-ID (Buyer)']);

  return {
    json: {
      ...item.json,
      bzst_request: {
        supplier_vat_id: sellerVat,
        buyer_vat_id: buyerVat,
        supplier_name: clean(invoice['Name (Seller)']),
        supplier_country: clean(invoice['Country (Seller)']),
        checked_at: new Date().toISOString(),
      }
    }
  };
});

function clean(value) {
  return String(value ?? '').trim();
}

function upper(value) {
  return clean(value).toUpperCase();
}

function arrayify(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) return [value.trim()];
  return [];
}

function pickBzstStatus(body, j) {
  return upper(
    body?.status ||
    body?.code ||
    body?.response_status ||
    j.response_status ||
    j.bzst_status_code ||
    j.error?.response_status ||
    j.error?.code
  );
}

function pickErrorMessage(j) {
  return clean(
    j.error?.message ||
    j.message ||
    j.error?.description ||
    j.error?.reason ||
    j.statusMessage
  );
}

return items.map(item => {
  const j = item.json || {};
  const invoice = j.invoice_extracted || {};
  const req = j.bzst_request || {};
  const body = j.body && typeof j.body === 'object' ? j.body : {};

  const bzstCode = pickBzstStatus(body, j);
  const errorMessage = pickErrorMessage(j);
  const errorCode = upper(j.error?.code || j.code);

  let status = 'error';
  let responseStatus = 'UNKNOWN_BZST_RESULT';
  let reasonCodes = arrayify(j.reason_codes);

  const isTransportError =
    !!errorMessage &&
    (
      errorCode === 'ECONNRESET' ||
      errorCode === 'ETIMEDOUT' ||
      errorCode === 'ECONNABORTED' ||
      upper(errorMessage).includes('ECONNRESET') ||
      upper(errorMessage).includes('ETIMEDOUT') ||
      upper(errorMessage).includes('TLS') ||
      upper(errorMessage).includes('SECURE TLS CONNECTION') ||
      upper(errorMessage).includes('SOCKET')
    );

  if (isTransportError) {
    status = 'error';

    if (
      errorCode === 'ECONNRESET' ||
      upper(errorMessage).includes('ECONNRESET') ||
      upper(errorMessage).includes('SECURE TLS CONNECTION')
    ) {
      responseStatus = 'TLS_CONNECTION_RESET';
      if (!reasonCodes.length) reasonCodes = ['BZST_TLS_CONNECTION_RESET'];
    } else if (
      errorCode === 'ETIMEDOUT' ||
      upper(errorMessage).includes('ETIMEDOUT')
    ) {
      responseStatus = 'BZST_TIMEOUT';
      if (!reasonCodes.length) reasonCodes = ['BZST_TIMEOUT'];
    } else {
      responseStatus = 'TRANSPORT_ERROR';
      if (!reasonCodes.length) reasonCodes = ['BZST_TRANSPORT_ERROR'];
    }
  } else if (bzstCode === 'EVATR-0000') {
    status = 'passed';
    responseStatus = 'EVATR-0000';
    reasonCodes = [];
  } else if (bzstCode === 'EVATR-0005') {
    status = 'failed';
    responseStatus = 'EVATR-0005';
    if (!reasonCodes.length) reasonCodes = ['EVATR-0005'];
  } else if (bzstCode === 'EVATR-0002') {
    status = 'error';
    responseStatus = 'EVATR-0002';
    if (!reasonCodes.length) reasonCodes = ['BZST_REQUEST_ERROR', 'EVATR-0002'];
  } else {
    status = 'error';
    responseStatus = bzstCode || 'UNKNOWN_BZST_RESULT';
    if (!reasonCodes.length && responseStatus) {
      reasonCodes = ['BZST_UNCLASSIFIED_ERROR', responseStatus];
    }
  }

  return {
    json: {
      ...j,
      k2_result: {
        status,
        control_id: 'CTRL-AP-002',
        control_title: 'Supplier VAT ID validation',
        supplier_vat_id: clean(req.supplier_vat_id || invoice['VAT-ID (Seller)']),
        buyer_vat_id: clean(req.buyer_vat_id || invoice['VAT-ID (Buyer)']),
        response_status: responseStatus,
        bzst_status_code: responseStatus,
        checked_at: clean(body.anfrageZeitpunkt || req.checked_at || new Date().toISOString()),
        reason_codes: reasonCodes,
        mode_frequency_count: Number(item.json.mode_frequency_count || 1),
      }
    }
  };
});

function clean(value) {
  return String(value || '').trim();
}

return items.map(item => {
  const invoice = item.json.invoice_extracted || {};

  return {
    json: {
      ...item.json,
      k2_result: {
        status: 'not_run',
        control_id: 'CTRL-AP-002',
        control_title: 'Supplier VAT ID validation',
        supplier_vat_id: clean(invoice['VAT-ID (Seller)']),
        buyer_vat_id: clean(invoice['VAT-ID (Buyer)']),
        response_status: 'domestic_not_checked',
        bzst_status_code: 'domestic_not_checked',
        checked_at: new Date().toISOString(),
        reason_codes: [],
        mode_frequency_count: Number(item.json.mode_frequency_count || 1),
      }
    }
  };
});

function clean(value) {
  return String(value || '').trim();
}

return items.map(item => {
  const invoice = item.json.invoice_extracted || {};

  return {
    json: {
      ...item.json,
      k2_result: {
        status: 'failed',
        control_id: 'CTRL-AP-002',
        control_title: 'Supplier VAT ID validation',
        supplier_vat_id: '',
        buyer_vat_id: clean(invoice['VAT-ID (Buyer)']),
        response_status: 'missing_vat_id',
        bzst_status_code: 'missing_vat_id',
        checked_at: new Date().toISOString(),
        reason_codes: ['VAT_ID_MISSING'],
        mode_frequency_count: Number(item.json.mode_frequency_count || 1),
      }
    }
  };
});

function clean(value) {
  return String(value ?? '').trim();
}

return items.map(item => {
  const j = item.json || {};
  const k1 = j.k1_result || {};
  const k2 = j.k2_result || {};
  const vatRoute = j.vat_route || {};

  const thresholdMode = Number(j.threshold_mode || 3);
  const thresholdTotal = Number(j.threshold_total || 6);
  const frequency = Number(k2.mode_frequency_count || j.mode_frequency_count || 1);

  const k1Status = clean(k1.status).toLowerCase();
  const k2Status = clean(k2.status).toLowerCase();
  const route = clean(vatRoute.route).toLowerCase();
  const responseStatus = clean(k2.response_status).toUpperCase();

  let trigger_reqeli = 'no';
  let trigger_flag = 'none';
  let trigger_reason = 'NO_TRIGGER';
  let rationale = 'No ReqEli trigger.';

  if (k1Status === 'failed') {
    trigger_reqeli = 'yes';
    trigger_flag = 'red';
    trigger_reason = 'K1_FAILED';
    rationale = 'Recipient validation failed.';
  } else if (k2Status === 'failed') {
    trigger_reqeli = 'yes';
    trigger_flag = 'red';
    trigger_reason = 'K2_FAILED';
    rationale = 'Supplier VAT validation failed.';
  } else if (k2Status === 'error') {
    trigger_reqeli = 'yes';
    trigger_flag = 'red';
    trigger_reason = 'K2_ERROR';
    rationale = `Supplier VAT validation could not be completed due to technical or service error (${responseStatus || 'unknown_error'}).`;
  } else if (route === 'domestic') {
    trigger_reqeli = 'no';
    trigger_flag = 'none';
    trigger_reason = 'DOMESTIC_PATH_NO_REQELI';
    rationale = 'Domestic invoice path: K1 passed and no foreign VAT validation issue exists.';
  }

  return {
    json: {
      ...j,
      threshold_mode: thresholdMode,
      threshold_total: thresholdTotal,
      mode_frequency_count: frequency,
      trigger_decision: {
        trigger_reqeli,
        trigger_flag,
        trigger_reason,
        rationale,
      }
    }
  };
});

function pick(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  const text = String(value).trim();
  return text === '' ? fallback : text;
}

function boolText(value) {
  if (
    value === true ||
    String(value).toLowerCase() === 'true' ||
    String(value).toLowerCase() === 'wahr'
  ) {
    return 'true';
  }
  if (
    value === false ||
    String(value).toLowerCase() === 'false' ||
    String(value).toLowerCase() === 'falsch'
  ) {
    return 'false';
  }
  return '';
}

function joinList(values) {
  if (!Array.isArray(values) || values.length === 0) return '';
  return values
    .map((v) => String(v || '').trim())
    .filter(Boolean)
    .join('; ');
}

function clean(value) {
  return String(value ?? '').replace(/^=/, '').trim();
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

function buildTimestampToken(value) {
  const date = value ? new Date(value) : new Date();
  const safeDate = Number.isNaN(date.getTime()) ? new Date() : date;

  const yyyy = safeDate.getUTCFullYear();
  const mm = pad2(safeDate.getUTCMonth() + 1);
  const dd = pad2(safeDate.getUTCDate());
  const hh = pad2(safeDate.getUTCHours());
  const mi = pad2(safeDate.getUTCMinutes());
  const ss = pad2(safeDate.getUTCSeconds());

  return `${yyyy}${mm}${dd}-${hh}${mi}${ss}`;
}

return items.map((item) => {
  const j = item.json || {};
  const invoice = j.invoice_extracted || {};
  const k1 = j.k1_result || {};
  const k2 = j.k2_result || {};
  const trigger = j.trigger_decision || {};

  const processId = pick(j.process_id, 'proc_ap_001');
  const processBuildId = pick(j.process_build_id, 'proc_ap_001@v0.1.0');
  const workflowId = pick(j.workflow_id, 'wf_invoice_check_x');

  const workflowRunId =
    pick(j.workflow_run_id) ||
    pick(j.execution_id) ||
    pick(j.n8n_execution_id) ||
    pick(j.run_id) ||
    pick(j.event_id);

  const reportedAt = pick(j.reported_at, new Date().toISOString());
  const timestampToken = pick(j.timestamp_token, buildTimestampToken(reportedAt));

  const incomingWorkflowReportId =
    pick(j.workflow_report_id) ||
    pick(j.source_report_id);

  const workflowReportBase =
    incomingWorkflowReportId ||
    `WF-${processId.toUpperCase().replace(/[^A-Z0-9]+/g, '-')}-${workflowRunId || 'NORUN'}`;

  const workflowReportId = workflowReportBase.endsWith(`-${timestampToken}`)
