  clean(input.run_id) ||
  clean(input.event_id) ||
  clean($execution?.id);

if (!processId) {
  throw new Error('Missing process_id for workflow report identity.');
}

if (!workflowRunId) {
  throw new Error('Missing workflow/execution id for workflow report identity.');
}

const existingWorkflowReportId =
  clean(input.workflow_report_id) ||
  clean(input.source_report_id);

const workflowReportId =
  existingWorkflowReportId ||
  `WF-${normalizeSegment(processId)}-${normalizeSegment(workflowRunId)}`;

if (!workflowReportId) {
  throw new Error('Could not resolve workflow_report_id.');
}

return [
  {
    json: {
      ...input,
      process_id: processId,
      workflow_run_id: workflowRunId,
      workflow_report_id: workflowReportId,
      source_report_id: workflowReportId,
    },
  },
];
